el('productionCostsForm').onsubmit=event=>{event.preventDefault();saveProductionCosts();};el('costMode').onchange=productionCostsChanged;for(const id of ['costInclusiveRegular','costInclusivePlus','costBaseRegular','costBasePlus'])el(id).oninput=productionCostsChanged;el('addCostComponent').onclick=()=>{if(el('costComponents').children.length>=20)return;appendCostComponent();productionCostsChanged();};el('loadProductionCosts').onclick=loadProductionCosts;el('reviewProductionCosts').onclick=()=>{if(!productionCostsConflict)return;productionCostsState=productionCostsConflict;productionCostsConflict=null;productionCostsBlocked=false;el('costsNotice').hidden=false;el('costsNotice').textContent='Versão atual revisada. Confira os rascunhos preservados antes de salvar.';el('costsStatus').textContent='Seus rascunhos serão salvos sobre a versão '+productionCostsState.revision+'.';updateProductionCostsPreview();if(bindingState)renderVariantCards();};
el('settings').onsubmit=event=>{event.preventDefault();try{if(!state)throw Error('Recarregue a página primeiro.');save({...state.values,regular_cents:amount('regular'),mixed_cents:amount('mixed'),plus_cents:amount('plus'),ad_share_percent:Number(el('share').value)},true);}catch(error){notice(error.message);}};
el('controls').onsubmit=event=>{event.preventDefault();try{if(!state)throw Error('Recarregue a página primeiro.');save({...state.values,hermes_mode:el('operation').value,daily_hour:Number(el('hour').value),monthly_budget_cents:el('billing').value==='subscription'?state.values.monthly_budget_cents:amount('budget'),run_reserve_cents:el('billing').value==='subscription'?state.values.run_reserve_cents:amount('reserve'),billing_mode:el('billing').value,monthly_run_limit:Number(el('runLimit').value)},false);}catch(error){notice(error.message);}};
el('run').onclick=async()=>{submitting=true;el('run').disabled=true;try{const job=await api('jobs',{});selectedJobId=job.id;notice('Análise adicionada à fila. Acompanhe o progresso abaixo.');}catch(error){notice(error.message);}finally{submitting=false;await pollLive();}};
el('storePeriodStartButton').onclick=()=>runStorePeriod('start');el('storePeriodContinue').onclick=()=>runStorePeriod('step');el('storePeriodStop').onclick=()=>{storePeriodStopRequested=true;storeResultMessage='A coleta será pausada após a resposta em andamento.';renderStoreResult();};el('storePeriodRecalculate').onclick=refreshStoreResult;el('storeAdjustmentsForm').onsubmit=event=>{event.preventDefault();saveStoreAdjustments();};for(const id of ['storeAdjustmentsAds','storeAdjustmentsExpenses'])el(id).oninput=storeAdjustmentsChanged;el('storeAdjustmentsRecharge').onchange=storeAdjustmentsChanged;el('variantsSync').onclick=()=>syncKnownVariants();defaultStorePeriodDates();renderStoreResult();
el('refresh').onclick=()=>Promise.all([pollLive(),loadTodayAds(),loadShopOrders()]);el('itemsRefresh').onclick=loadVariants;el('discardBindingDrafts').onclick=()=>{if(bindingSaving||itemsPromise)return;bindingDrafts.clear();notice('Rascunhos dos vínculos descartados. Os vínculos salvos foram preservados.');renderVariantCards();};el('saveObservation').onclick=saveObservation;el('observationsRefresh').onclick=()=>loadObservations(false,true);el('observationsMore').onclick=()=>loadObservations(true);el('bindingsForm').onsubmit=event=>{event.preventDefault();saveVariantBindings();};el('reviewBindingVersion').onclick=()=>{if(!bindingConflict)return;bindingState=bindingConflict;bindingConflict=null;bindingStale=false;bindingLoadFailed=false;el('bindingsNotice').hidden=false;el('bindingsNotice').textContent='Versão atual carregada. Confira os rascunhos preservados antes de salvar.';renderVariantCards();};el('billing').onchange=billingHelp;el('male').onchange=simulate;el('female').onchange=simulate;
const productFilters=el('productFilters');if(productFilters)productFilters.open=!!(window.matchMedia&&window.matchMedia('(min-width: 760px)').matches);
el('productSearch').oninput=()=>{productBrowserPage=1;renderVariantCards();};el('productSearch').onkeydown=event=>{if(event.key==='Enter')event.preventDefault();};for(const id of ['productStatusFilter','productTypeFilter','productSort','productPageSize'])el(id).onchange=()=>{productBrowserPage=1;renderVariantCards();};el('productPrevious').onclick=()=>{if(productBrowserPage>1){productBrowserPage--;renderVariantCards();el('variantCards').scrollIntoView({block:'start'});}};el('productNext').onclick=()=>{if(!el('productNext').disabled){productBrowserPage++;renderVariantCards();el('variantCards').scrollIntoView({block:'start'});}};el('productClearFilters').onclick=resetProductBrowserFilters;
el('logout').onsubmit=event=>{event.preventDefault();clearTimeout(pollTimer);fetch('/admin/logout',{method:'POST',headers:{'X-CSRF-Token':csrf}}).then(response=>{if(response.ok)location.href='/admin/login';else{notice('Recarregue a página antes de sair.');schedulePoll();}});};
function openTab(tab){const titles={overview:['Resumo da loja','Repasses, custos de produção e resultado do período em um só lugar.'],margins:['Custos de produção','Seu perfil de custos é aplicado automaticamente a camisetas e kits.'],hermes:['Central do Hermes','Acompanhe análises, operação e limites de uso.'],products:['Catálogo inteligente','Composições, tamanhos e custos identificados automaticamente. Revise somente as exceções.'],history:['Histórico e auditoria','Consulte as versões salvas e acompanhe as alterações.'],roadmap:['Evolução da operação','Os próximos passos para ampliar as análises e a automação.']};if(!Object.hasOwn(titles,tab))tab='overview';if(tab==='products'){if(state)loadObservations();syncOnProductsOpen();}document.querySelectorAll('main section').forEach(section=>section.hidden=section.id!==tab);document.querySelectorAll('[data-tab]').forEach(button=>{const selected=button.dataset.tab===tab;button.classList.toggle('active',selected);if(selected)button.setAttribute('aria-current','page');else button.removeAttribute('aria-current');});el('pageTitle').textContent=titles[tab][0];el('pageSubtitle').textContent=titles[tab][1];document.documentElement.dataset.activePanel=tab;}

document.querySelectorAll('[data-tab]').forEach(button=>button.onclick=()=>openTab(button.dataset.tab));document.querySelectorAll('[data-open]').forEach(button=>button.onclick=()=>openTab(button.dataset.open));
document.addEventListener('visibilitychange',()=>{if(document.hidden)clearTimeout(pollTimer);else if(state)pollLive();});
setInterval(()=>{if(document.hidden)return;updateShopSnapshotAge();updateObservationCaptureState();for(const button of el('jobs').querySelectorAll('[data-job-id]')){const job=rows.find(row=>row.id===button.dataset.jobId);if(job)button.textContent=jobLabel(job);}const selected=rows.find(job=>job.id===selectedJobId);if(selected&&['queued','running'].includes(selected.status))selectedResult();},1000);
initialize();
